import http from 'http';
import assert from 'assert';
import axios from '/data1/zhangyixiang/HuaWei/SWE-bench-FeatureEnvy-test/.tmp/opencode-swebench-fqgrd8z4/testbed/index.js';

const server = http.createServer((req, res) => {
  const chunks = [];
  req.on('data', (c) => chunks.push(c));
  req.on('end', () => {
    res.setHeader('content-type', 'application/json');
    res.end(JSON.stringify({
      headers: req.headers,
      body: Buffer.concat(chunks).toString('utf8')
    }));
  });
});

await new Promise((resolve) => server.listen(0, resolve));
const url = `http://localhost:${server.address().port}`;

try {
  const form = new FormData();
  form.append('someProperty', 'someValue');
  form.append('newline', 'a\nb');
  form.append('file1', new Blob(['blob-content'], {type: 'image/jpeg'}), 'test.jpg');

  const {data} = await axios.post(url, form);
  assert.match(data.headers['content-type'], /^multipart\/form-data; boundary=/);
  assert.strictEqual(Number(data.headers['content-length']), Buffer.byteLength(data.body));
  assert.match(data.body, /name="someProperty"\r\n\r\nsomeValue/);
  assert.match(data.body, /name="newline"\r\n\r\na\r\nb/);
  assert.match(data.body, /name="file1"; filename="test.jpg"/);
  assert.match(data.body, /Content-Type: image\/jpeg/);
  assert.match(data.body, /blob-content/);
  console.log('FormData OK');

  const blob = new Blob(['blob-content'], {type: 'text/plain'});
  const blobRes = await axios.post(url, blob);
  assert.strictEqual(blobRes.data.body, 'blob-content');
  assert.strictEqual(blobRes.data.headers['content-type'], 'text/plain');
  assert.strictEqual(Number(blobRes.data.headers['content-length']), 12);
  console.log('Blob OK');

  const customForm = new FormData();
  customForm.append('foo', 'bar');
  const customRes = await axios.post(url, customForm, {
    headers: {'Content-Type': 'multipart/form-data; boundary=----CustomBoundary12345'}
  });
  assert.match(customRes.data.body, /^------CustomBoundary12345\r\n/);
  assert.match(customRes.data.headers['content-type'], /boundary=----CustomBoundary12345/);
  console.log('Custom boundary OK');
} finally {
  server.close();
}

